let LV={t:0,ok:0,err:[],net:false,busy:false};
const NETMSG2='This page can’t reach mfapi.in, so prices can’t refresh here. Inside Claude the browser blocks outside requests. Update prices by hand, or use a hosted copy.';
const liveMsg=()=>{if(!LV.t)return '';if(LV.net&&!LV.ok)return NETMSG2;if(LV.nm&&!LV.ok)return LV.nm+' fund'+(LV.nm===1?'':'s')+' couldn’t be matched. Import your CAS again so each fund’s ISIN is saved.';if(!LV.ok&&LV.err.length)return LV.err.join('. ');return(LV.ch?'Updated '+LV.ch+' of '+LV.ok+' fund'+(LV.ok===1?'':'s')+' with newer prices':'Prices are already the latest')+(LV.nd?' ('+fd(LV.nd)+')':'')+'.'+(LV.err.length?' '+LV.err.join('. ')+'.':'')};
const liveNote=()=>LV.busy?' Fetching live NAVs…':LV.t?(LV.net&&!LV.ok?' Can’t reach mfapi.in from here.':LV.nm&&!LV.ok?' '+LV.nm+' fund'+(LV.nm===1?'':'s')+' not matched, re-import your CAS.':!LV.ok&&LV.err.length?' Couldn’t refresh, tap to retry.':' Live NAVs fetched '+new Date(LV.t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'.'):'';
async function liveGet(code){const all=await indiaLatest(),a=all&&all.find(x=>String(x.schemeCode)===String(code));if(a)return{nav:Number(a.nav),date:pd(a.date),meta:{isin_growth:a.isinGrowth,isin_div_reinvestment:a.isinDivReinvestment}};const r=await fetch('https://api.mfapi.in/mf/'+encodeURIComponent(code)+'/latest',{signal:AbortSignal.timeout?AbortSignal.timeout(10000):undefined});if(!r.ok)throw new Error('Scheme code '+code+' returned HTTP '+r.status);const j=await r.json(),d=j&&j.data&&j.data[0],nav=d?parseFloat(d.nav):NaN;if(!(nav>0))throw new Error('Scheme code '+code+' has no NAV');return{nav,date:pd(d.date)||today(),meta:j.meta||{}}}
function saveSc(){S.sc=S.sc||{};document.querySelectorAll('[data-sc]').forEach(i=>{const v=i.value.trim();if(v)S.sc[i.dataset.sc]=v;else delete S.sc[i.dataset.sc]});save()}
function toast(msg,act,lab){const o=$('#toast');if(o)o.remove();const t=document.createElement('div');t.id='toast';t.setAttribute('role','status');t.innerHTML=`<span>${esc(msg)}</span>${act?`<button ${act}>${esc(lab)}</button>`:''}`;document.body.appendChild(t);clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.remove(),8000);const b=t.querySelector('button');if(b)b.addEventListener('click',()=>t.remove())}
document.addEventListener('click',e=>{if(!e.target.closest('[data-a=livego]'))return;if(!calc().open.some(h=>{const t=S.tx.find(x=>x.name===h.name);return t&&t.type==='mf'})){toast('There are no mutual funds to refresh. Stock prices are updated by hand under Holdings, Update prices.');return}const m0=$('#lvm');if(m0)m0.textContent='Fetching…';toast('Checking for the latest NAVs…');liveRefresh(true).then(()=>{const m=$('#lvm');if(m)m.textContent=liveMsg();const bad=!LV.ok;toast(liveMsg(),bad&&LV.net?"data-a='prices'":bad&&LV.nm?"data-t='data'":'',bad&&LV.net?'Update prices':'Import CAS')})});
